/// <summary>警示 Warning: Police-style double strobe alternating between the two halves and colors.</summary>
public sealed class WarningEffect : EffectGenerator, ILoopable
{
    public const string EffectId = "Warning";

    public WarningEffect()
        : base(EffectId, new EffectParamSchema("Warning", "警示", 2, 2, true, false, EffectMath.Duo, true))
